"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["36824"],{62975(e){e.exports=JSON.parse('{"id":"F149","slug":"beneish-m-score","name":"Beneish M-Score","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Accounting fraud warning signs","level":"Intermediate","aliases":["earnings manipulation","accounting fraud warning signs","fraud detection model"],"formula":{"latex":"M=-4.84+0.920\\\\,DSRI+0.528\\\\,GMI+0.404\\\\,AQI+0.892\\\\,SGI+0.115\\\\,DEPI-0.172\\\\,SGAI+4.679\\\\,TATA-0.327\\\\,LVGI","also":[],"text":"M = -4.84 + 0.920 x DSRI + 0.528 x GMI + 0.404 x AQI + 0.892 x SGI + 0.115 x DEPI - 0.172 x SGAI + 4.679 x TATA - 0.327 x LVGI. A score above about -1.78 flags a likely manipulator"},"symbols":[{"symbol":"DSRI","meaning":"Days sales in receivables index: this year\'s DSO / last year\'s","unit":"number"},{"symbol":"GMI","meaning":"Gross margin index: last year\'s gross margin / this year\'s","unit":"number"},{"symbol":"AQI","meaning":"Asset quality index: share of non-current assets other than PP&E, this year / last year","unit":"number"},{"symbol":"SGI","meaning":"Sales growth index: sales this year / last year","unit":"number"},{"symbol":"DEPI","meaning":"Depreciation index: depreciation rate last year / this year","unit":"number"},{"symbol":"SGAI","meaning":"SG&A expense index: SG&A to sales, this year / last year","unit":"number"},{"symbol":"TATA","meaning":"Total accruals to total assets: (Income from continuing operations - CFO) / total assets","unit":"number"},{"symbol":"LVGI","meaning":"Leverage index: (debt / assets) this year / last year","unit":"number"}],"when_to_use":"Use it as a screen for earnings manipulation. Eight ratios, mostly comparing this year with last year, are combined into one score. It is a statistical flag, not proof of fraud, and gives false alarms, especially for fast-growing firms. Use it to decide where to look harder.","worked_example":{"problem":"A company\'s indexes are DSRI 1.20, GMI 1.05, AQI 1.10, SGI 1.25, DEPI 1.00, SGAI 0.95, TATA 0.03 and LVGI 1.05.","inputs":{"dsri":1.2,"gmi":1.05,"aqi":1.1,"sgi":1.25,"depi":1,"sgai":0.95,"tata":0.03,"lvgi":1.05},"steps":[{"label":"M = -4.84 + 0.920 DSRI + 0.528 GMI + 0.404 AQI + 0.892 SGI + 0.115 DEPI - 0.172 SGAI + 4.679 TATA - 0.327 LVGI","working":"-4.84+0.920 x 1.2+0.528 x 1.05+0.404 x 1.1+0.892 x 1.25+0.115 x 1-0.172 x 0.95+4.679 x 0.03-0.327 x 1.05","value":"-1.87"},{"label":"Distance below (negative) or above (positive) the -1.78 cut-off","working":"-1.87358+1.78","value":"-0.09"}],"answer":"The M-score is -1.87. The usual cut-off is -1.78, and this score is on the borderline, so the company is not clearly flagged, but receivables growing faster than sales (DSRI) and strong sales growth (SGI) are the items to look into first."},"calculator":{"available":true,"inputs":[{"id":"dsri","label":"DSRI","unit":"","type":"number","default":1.2,"hint":""},{"id":"gmi","label":"GMI","unit":"","type":"number","default":1.05,"hint":""},{"id":"aqi","label":"AQI","unit":"","type":"number","default":1.1,"hint":""},{"id":"sgi","label":"SGI","unit":"","type":"number","default":1.25,"hint":""},{"id":"depi","label":"DEPI","unit":"","type":"number","default":1,"hint":""},{"id":"sgai","label":"SGAI","unit":"","type":"number","default":0.95,"hint":""},{"id":"tata","label":"TATA","unit":"","type":"number","default":0.03,"hint":""},{"id":"lvgi","label":"LVGI","unit":"","type":"number","default":1.05,"hint":""}],"checks":[],"steps":[{"id":"m","label":"M = -4.84 + 0.920 DSRI + 0.528 GMI + 0.404 AQI + 0.892 SGI + 0.115 DEPI - 0.172 SGAI + 4.679 TATA - 0.327 LVGI","expr":"-4.84+0.920*dsri+0.528*gmi+0.404*aqi+0.892*sgi+0.115*depi-0.172*sgai+4.679*tata-0.327*lvgi","format":"num2"},{"id":"gap","label":"Distance below (negative) or above (positive) the -1.78 cut-off","expr":"m+1.78","format":"num2"}],"results":["m","gap"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"m":-1.8735799999999996,"gap":-0.09357999999999955}},"finder":{"finds":"A flag for possible earnings manipulation","needs":"The eight index values"},"related":[{"slug":"accrual-ratio","name":"Accrual Ratio (Earnings Quality)"},{"slug":"altman-z-score","name":"Altman Z-Score"},{"slug":"days-sales-outstanding","name":"Days Sales Outstanding and Receivables Turnover"}],"related_ids":["F137","F301","F192"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>M</mi><mo>=</mo><mo>\u2212</mo><mn>4.84</mn><mo>+</mo><mn>0.920</mn><mtext>\u2009</mtext><mi>D</mi><mi>S</mi><mi>R</mi><mi>I</mi><mo>+</mo><mn>0.528</mn><mtext>\u2009</mtext><mi>G</mi><mi>M</mi><mi>I</mi><mo>+</mo><mn>0.404</mn><mtext>\u2009</mtext><mi>A</mi><mi>Q</mi><mi>I</mi><mo>+</mo><mn>0.892</mn><mtext>\u2009</mtext><mi>S</mi><mi>G</mi><mi>I</mi><mo>+</mo><mn>0.115</mn><mtext>\u2009</mtext><mi>D</mi><mi>E</mi><mi>P</mi><mi>I</mi><mo>\u2212</mo><mn>0.172</mn><mtext>\u2009</mtext><mi>S</mi><mi>G</mi><mi>A</mi><mi>I</mi><mo>+</mo><mn>4.679</mn><mtext>\u2009</mtext><mi>T</mi><mi>A</mi><mi>T</mi><mi>A</mi><mo>\u2212</mo><mn>0.327</mn><mtext>\u2009</mtext><mi>L</mi><mi>V</mi><mi>G</mi><mi>I</mi></mrow><annotation encoding=\\"application/x-tex\\">M=-4.84+0.920\\\\,DSRI+0.528\\\\,GMI+0.404\\\\,AQI+0.892\\\\,SGI+0.115\\\\,DEPI-0.172\\\\,SGAI+4.679\\\\,TATA-0.327\\\\,LVGI</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"bayes-theorem","name":"Bayes\' Theorem"},"next":{"slug":"best-execution-price-improvement","name":"Best Execution: Price Improvement and Execution Cost"},"lesson":null,"total":522}')}}]);